# https://scikit-learn.org/stable/modules/svm.html

import numpy as np
import util
from sklearn import svm
from sklearn.model_selection import GridSearchCV
from sklearn.metrics import roc_auc_score
import time


def train_svm(filename, X_train, X_test, y_train, y_test, solver='rbf', full_param=False, debug=False, numFolds=10,
              njobs=-1, scalar=1, make_graphs=False, pSVM={}):
    base_params = {'kernel': solver, 'probability': True, 'random_state': 1}

    if len(pSVM) > 0:
        params = dict(pSVM)
        params['probability'] = True  # ROC-AUC needs predict_proba
        params.setdefault('random_state', 1)
        clf = svm.SVC(**params)
    else:
        if solver == 'rbf':
            param_grid = {'C'    : [0.1, 1, 10, 100, 1000],
                          'gamma': [0.0000001, 0.00001, 0.001, 0.1, 1.0, 'scale']}
        elif solver == 'linear':
            param_grid = {'C': [0.1, 1, 10, 100, 1000]}
        elif solver == 'poly':
            param_grid = {'C'     : [0.1, 1, 10, 100],
                          'gamma' : [0.001, 0.1, 1.0, 'scale'],
                          'degree': [2, 3, 4]}
        else:  # sigmoid and any other kernel
            param_grid = {'C'    : [0.1, 1, 10, 100, 1000],
                          'gamma': [0.0000001, 0.00001, 0.001, 0.1, 1.0, 'scale']}

        gs = GridSearchCV(svm.SVC(**base_params), param_grid=param_grid, cv=numFolds, n_jobs=njobs,
                          scoring='roc_auc_ovr_weighted', verbose=debug)
        gs.fit(X_train, y_train)
        clf = gs.best_estimator_

        if debug:
            print('SVM ({0}) best params: {1}'.format(solver, gs.best_params_))
            print('SVM ({0}) best CV score: {1}'.format(solver, gs.best_score_))

        if full_param:
            util.save_gridsearch_to_csv(gs.cv_results_, 'SVM', filename, scalar, solver)

        if make_graphs:
            util.plot_learning_curve(clf, 'SVM-' + solver, filename, X_train, y_train, cv=numFolds, n_jobs=njobs,
                                     debug=debug)
            if solver == 'rbf':
                util.svm_rbf_C_Gamma_viz(X_train, y_train, base_params, njobs, filename, 0.5)

    start = time.time()
    clf.fit(X_train, y_train)
    runTime = time.time() - start

    train_score = roc_auc_score(y_train, clf.predict_proba(X_train), multi_class='ovr', average='weighted')
    test_score = roc_auc_score(y_test, clf.predict_proba(X_test), multi_class='ovr', average='weighted')

    return runTime, train_score, test_score
